#include <cstdio>
#include <vector>

int main() {
    int n;
    long long k;
    scanf("%d %lld", &n, &k);
    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) scanf("%d", &a[i]);

    k %= n;
    for (int i = 0; i < n; ++i) {
        if (i) printf(" ");
        int idx = ((i - (int)k) % n + n) % n;
        printf("%d", a[idx]);
    }
    printf("\n");
    return 0;
}
